package br.com.serviceflow.api.controller;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*; import static org.hamcrest.Matchers.*; import com.fasterxml.jackson.databind.*; import org.junit.jupiter.api.*; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.http.MediaType; import org.springframework.test.web.servlet.MockMvc;
@SpringBootTest @AutoConfigureMockMvc class ClienteCrudTest {
 @Autowired MockMvc mvc; @Autowired ObjectMapper json; private String auth() throws Exception {String r=mvc.perform(post("/api/v2/auth/login").contentType(MediaType.APPLICATION_JSON).content("{\"email\":\"admin@brilhototal.com.br\",\"password\":\"AdminTest@123\"}")).andReturn().getResponse().getContentAsString();return "Bearer "+json.readTree(r).get("accessToken").asText();}
 @Test void completeCrud() throws Exception {String token=auth();String created=mvc.perform(post("/api/v2/clientes").header("Authorization",token).contentType(MediaType.APPLICATION_JSON).content("{\"name\":\"Ana\",\"phone\":\"11999999999\"}")).andExpect(status().isOk()).andExpect(jsonPath("$.name",is("Ana"))).andReturn().getResponse().getContentAsString();long id=json.readTree(created).get("id").asLong();mvc.perform(get("/api/v2/clientes/"+id).header("Authorization",token)).andExpect(status().isOk());mvc.perform(put("/api/v2/clientes/"+id).header("Authorization",token).contentType(MediaType.APPLICATION_JSON).content("{\"name\":\"Ana Silva\",\"phone\":\"11888888888\"}")).andExpect(status().isOk()).andExpect(jsonPath("$.name",is("Ana Silva")));mvc.perform(delete("/api/v2/clientes/"+id).header("Authorization",token)).andExpect(status().isNoContent());mvc.perform(get("/api/v2/clientes/"+id).header("Authorization",token)).andExpect(status().isNotFound());}
}
